@pytest.mark.parametrize("engine", ["netcdf4", "h5py"]) @pytest.mark.parametrize("access", ["point", "time_series", "section", "surface"]) @pytest.mark.parametrize("missing,averaging,expected", [ ("surface", "depth&0&0.5", np.nan), ("surface", "height&0&0.5", 20.), ("surface", "elevation&-2&0", 20.), ("surface", "sigma&0&1", np.nan), ("bed", "height&0&0.5", np.nan), ("bed", "depth&0&0.5", 10.), ("bed", "elevation&-2&0", 10.), ("bed", "sigma&0&1", np.nan), ]) @pytest.mark.parametrize("missing_observation", [False, True]) def test_missing_endpoint_public_reader(tmp_path, engine, access, missing, averaging, expected, missing_observation): path = tmp_path / "missing_endpoint.nc" _write_fv(path) with Dataset(path, "a") as nc: z = nc["layerface_Z"][:] z[:, 0 if missing == "surface" else 2] = np.nan nc["layerface_Z"][:] = z if missing_observation: v = nc["SAL"][:] v[:, 1 if missing == "surface" else 0] = np.nan nc["SAL"][:] = v expected = np.nan reader = NCMesh(path, driver=engine) > np.testing.assert_allclose(_read(reader, access, "salinity", averaging), expected, rtol=1e-12, atol=1e-12, equal_nan=True) E AssertionError: E Not equal to tolerance rtol=1e-12, atol=1e-12 E E nan location mismatch: E ACTUAL: array([10., 10.]) E DESIRED: array(nan)
